var _wheels=[];
// Wheel meshes in the Crown Vic GLB have geometry that is NOT centred on the mesh
// origin (Sketchfab bakes large translations into the nodes). Spinning those meshes
// in place rotated them around a far-away local pivot, so the wheels visibly flew
// off / detached from the car. Instead, every wheel mesh is re-parented (world
// transform preserved via .attach) under a fresh pivot placed at the wheel's real
// centre in carRig space, and the PIVOT is what spins about the axle (rig-local X).
function _collectWheels(root){
  if(!root)return;
  carRig.updateMatrixWorld(true);
  var meshes=[];
  root.traverse(function(o){
    // NB: bare "rim" must not match body "trim"/"reartrim"/"moulding_trim" meshes —
    // the lookbehind keeps real rims/tyres while excluding chrome body trim, which
    // the old pattern wrongly spun as if it were a wheel.
    if(o.isMesh && /wheel|tyre|tire|(?<![a-z])rim/i.test(o.name||'')) meshes.push(o);
  });
  var _bb=new THREE.Box3(), _size=new THREE.Vector3(), _ctr=new THREE.Vector3();
  for (var i=0;i<meshes.length;i++){
    var o=meshes[i];
    _bb.setFromObject(o);
    if (_bb.isEmpty()) continue;
    _bb.getSize(_size); _bb.getCenter(_ctr);
    var maxDim=Math.max(_size.x,_size.y,_size.z);
    // A single wheel on a ~4.4-long car is well under 1.6 units across; anything
    // bigger spans several wheels / an axle and is safer left static than mangled.
    if (maxDim>1.6 || maxDim<0.05) continue;
    var pivot=new THREE.Object3D();
    carRig.add(pivot);
    pivot.position.copy(carRig.worldToLocal(_ctr.clone()));
    pivot.updateMatrixWorld(true);
    pivot.attach(o);                       // keeps the wheel exactly where it sits
    _wheels.push({mesh:pivot, axis:new THREE.Vector3(1,0,0), radius:Math.max(0.2,_size.y/2)});
  }
}
// Remove old wheel pivots (and the meshes attached under them) from carRig —
// needed when the real model replaces the fallback car.
function _dropWheels(){
  for (var i=0;i<_wheels.length;i++){ var p=_wheels[i].mesh; if(p&&p.parent)p.parent.remove(p); }
  _wheels.length=0;
}
