/* GPS route: shortest street-grid route to the goal. Streets are snapped TOWARD
   the goal (a street always exists between the car and the goal, since the goal
   sits on one), so no leg ever backtracks — total length equals the Manhattan
   distance, which is the minimum on a full grid. The two equal-length L orders
   (turn-then-run vs run-then-turn) are tie-broken by whichever first leg points
   closest to the car's current heading, so the route never draws a U-turn the
   player doesn't need. Every leg lies on a road; never cuts through blocks. */
function routeToGoal(){
  // nearest street centre to v that lies between v and target (inclusive)
  function snapToward(v,target){
    var b=null,d=Infinity;
    for(var i=0;i<streetCenters.length;i++){ var s=streetCenters[i];
      if((s-v)*(s-target)<=0){ var dd=Math.abs(v-s); if(dd<d){d=dd;b=s;} } }
    return b===null?target:b; // null can't happen (target is a street); stay safe
  }
  function build(raw){ // drop only true duplicates — never merge a snap point
    // into the next leg, or a tiny lateral offset would skew a long leg off
    // its street line. Sub-unit legs are harmless (rounded caps swallow them).
    var pts=[raw[0]];
    for(var i=1;i<raw.length;i++){ var l=pts[pts.length-1],q=raw[i];
      if(Math.abs(l[0]-q[0])>0.05||Math.abs(l[1]-q[1])>0.05)pts.push(q); }
    return pts;
  }
  function firstDot(pts,fx,fz){ // alignment of first SIGNIFICANT leg with heading
    for(var i=1;i<pts.length;i++){
      var dx=pts[i][0]-pts[i-1][0], dz=pts[i][1]-pts[i-1][1], m=Math.hypot(dx,dz);
      if(m>0.6)return (dx*fx+dz*fz)/m;
    }
    return 0;
  }
  var sx=snapToward(pos.x,GOAL.x), sz=snapToward(pos.z,GOAL.z);
  var A=build([[pos.x,pos.z],[sx,pos.z],[sx,GOAL.z],[GOAL.x,GOAL.z]]);
  var B=build([[pos.x,pos.z],[pos.x,sz],[GOAL.x,sz],[GOAL.x,GOAL.z]]);
  var fx=Math.sin(heading), fz=Math.cos(heading);
  return firstDot(A,fx,fz)>=firstDot(B,fx,fz)?A:B;
}

function _mmWorldPoly(b){
  var shape = b.kind==='church'
    ? [[-0.34,-0.5],[0.34,-0.5],[0.34,-0.12],[0.18,-0.12],[0.18,0.5],[-0.18,0.5],[-0.18,-0.12],[-0.34,-0.12]]
    : b.kind==='grocery'
      ? [[-0.5,-0.5],[0.5,-0.5],[0.5,0.22],[0.14,0.22],[0.14,0.5],[-0.14,0.5],[-0.14,0.22],[-0.5,0.22]]
      : [[-0.5,-0.5],[0.5,-0.5],[0.5,0.5],[-0.5,0.5]];
  var cx=(b.x0+b.x1)*0.5, cz=(b.z0+b.z1)*0.5, sx=b.x1-b.x0, sz=b.z1-b.z0, rot=(b.rot||0)&3;
  var out=new Array(shape.length);
  for(var i=0;i<shape.length;i++){
    var px=shape[i][0]*sx, pz=shape[i][1]*sz, t;
    if(rot===1){ t=px; px=pz; pz=-t; }
    else if(rot===2){ px=-px; pz=-pz; }
    else if(rot===3){ t=px; px=-pz; pz=t; }
    out[i]=[cx+px,cz+pz];
  }
  return out;
}
function _mmInsetPoly(poly,t){
  var cx=0, cz=0;
  for(var i=0;i<poly.length;i++){ cx+=poly[i][0]; cz+=poly[i][1]; }
  cx/=poly.length; cz/=poly.length;
  var out=new Array(poly.length);
  for(var j=0;j<poly.length;j++)out[j]=[cx+(poly[j][0]-cx)*t, cz+(poly[j][1]-cz)*t];
  return out;
}
function _mmHeight01(b){ return Math.max(0,Math.min(1,((b.height||18)-8)/56)); }
function _mmBuildingFill(b,h01){
  if(b.kind==='church') return 'rgb(30,42,34)';
  if(b.kind==='grocery') return 'rgb(26,38,31)';
  var shade=20+Math.round(h01*24);
  return 'rgb('+shade+','+(shade+10)+','+(shade+6)+')';
}
function _mmRoofFill(b,h01){
  if(b.kind==='church') return 'rgba(86,110,96,0.66)';
  if(b.kind==='grocery') return 'rgba(74,96,82,0.66)';
  var shade=60+Math.round(h01*40);
  return 'rgba('+shade+','+(shade+16)+','+(shade+8)+',0.64)';
}
